    const items=values.map((value,index)=>({label:state === "long" ? ["지_긴_이름과_조건을_포함한_설명_라벨","덕_긴_이름과_조건을_포함한_설명_라벨","용_긴_이름과_조건을_포함한_설명_라벨"][index] : ["지","덕","용"][index],value}));
